import{_ as n,C as r,c as l,o as i,a9 as s,G as o}from"./chunks/framework.DuenUNqn.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/wiki"},{"title":"TownyAdvanced","link":"/wiki/TownyAdvanced"},{"title":"towny-advanced","link":""},{"title":"常见问题","link":"/wiki/TownyAdvanced/towny-advanced/faq"}]},"headers":[],"relativePath":"wiki/TownyAdvanced/towny-advanced/faq.md","filePath":"wiki/TownyAdvanced/towny-advanced/faq.md"}'),c={name:"wiki/TownyAdvanced/towny-advanced/faq.md"};function w(g,e,p,d,f,h){const t=r("NolebaseGitContributors"),a=r("NolebaseGitChangelog");return i(),l("div",null,[e[0]||(e[0]=s('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><p>问：为什么玩家不能在城镇之外的郊区破坏或放置方块？</p><p>答：使用命令 <code>/ta toggle wildernessuse</code>。</p><hr><p>问：为什么城镇战败或解除占领后，原本的建筑逐渐回溯消失。怎么做才可以阻止它？</p><p>问：在各自世界使用命令 <code>/tw toggle revertunclaim</code>。</p><blockquote><ul><li><a href="./../reference/configs/config-yml">配置文件</a>中的新世界设置仅对新生成的世界生效，这在设置附近的注释中有所讲解，<a href="./../setup/installation">安装教程</a>与<a href="./../towny-advanced/how-towny-works">插件运作原理</a>章节中亦有提及。你需要通过 /tw toggle 命令或在 世界名称.txt 文件中对其手动设置。</li></ul></blockquote><hr><p>问：你推荐什么经济插件与 Towny 一同使用？</p><p>答：你有很多选择：</p><blockquote><ul><li>复杂： <ul><li><a href="https://www.spigotmc.org/resources/7805/" target="_blank" rel="noreferrer">The New Economy</a></li><li><a href="https://www.spigotmc.org/resources/83862/" target="_blank" rel="noreferrer">lightEconomy</a></li></ul></li><li>简单： <ul><li><a href="https://www.spigotmc.org/resources/67355/" target="_blank" rel="noreferrer">HellConomy</a></li><li><a href="https://github.com/LlmDl/iConomyUnlocked" target="_blank" rel="noreferrer">iConomyUnlocked</a> - 需将 Towny 从旧经济模式升级。</li></ul></li><li>实际上所有经济插件都有效。你仍然需要安装 Vault 或 <a href="https://www.spigotmc.org/resources/50739/" target="_blank" rel="noreferrer">Reserve</a> 才可让 Towny 与你选择的经济插件正常对接。</li><li>已知不兼容的插件：Scruffyboy12 所写的 <a href="https://www.spigotmc.org/resources/87053/" target="_blank" rel="noreferrer">Economy</a>、EssentialsEconomy、<a href="https://www.spigotmc.org/resources/sunlight-%E2%AD%90-best-z-essentials-cmi-alternative.67733/" target="_blank" rel="noreferrer">Sunlight</a>、<a href="https://www.spigotmc.org/resources/liteeco-simple-economy-plugin-1-21-x.101934/" target="_blank" rel="noreferrer">LiteEco</a>、<a href="https://www.spigotmc.org/resources/%E2%9C%85-worldserver-%E2%96%B6-per-world-chat-tab-and-eco.99010/" target="_blank" rel="noreferrer">WorldServer</a>、Pro_Nil 所写的 <a href="https://github.com/Pro-Nil/Economy" target="_blank" rel="noreferrer">Economy</a>、<a href="https://www.spigotmc.org/resources/playerpoints.80745/" target="_blank" rel="noreferrer">PlayerPoints</a>、YiC200333 所写的 <a href="https://www.spigotmc.org/resources/xconomy.75669/" target="_blank" rel="noreferrer">XConomy</a>、<a href="https://www.spigotmc.org/resources/coinsengine-%E2%AD%90-economy-and-custom-currencies.84121/" target="_blank" rel="noreferrer">CoinsEngine</a>。</li></ul></blockquote>',11)),o(t),o(a)])}const _=n(c,[["render",w]]);export{u as __pageData,_ as default};
